"""Fits version B's correction (notes 21.65) and runs the carry-forward slope test on the fitting period."""
import numpy as np, pandas as pd, warnings; warnings.filterwarnings("ignore")
import market1 as M, vb
SP = M.SP; P = np.load(f"{SP}/out/market1n_post.npz"); th = {k: float(np.median(P[k])) for k in M.PN}; R = pd.read_parquet(f"{SP}/out/da_rows.parquet"); R["Dp"] = R.rl - R.other; R["r"] = R.p / R.L; R["nb"] = R.X - R.eX - M.other_curves(th, R.p.values, R.L.values)[0]
F = R[R.tr].dropna(subset=["sh_da", "eX_da", "Dp", "r"]).copy(); print("fitting hours with day-ahead data:", len(F)); B = vb.basis(F.r.values); q = np.quantile(F.Dp, np.linspace(0.1, 0.9, 9)); Zf = lambda d: np.column_stack([np.ones_like(d), d] + [np.maximum(d - k, 0.0) for k in q]); Z = Zf(F.Dp.values); Bh = Z @ np.linalg.lstsq(Z, B, rcond=None)[0]
print("first stage R2 per basis column:", np.round(1 - (B - Bh)[:, 1:].var(0) / B[:, 1:].var(0), 2)); co = {}
for nm in ("sh_da", "eX_da"):
    y = F[nm].values; co[nm] = np.linalg.lstsq(Bh, y, rcond=None)[0]; ols = np.linalg.lstsq(B, y, rcond=None)[0]; g = np.array([-0.1, 0.1, 0.3, 0.5, 0.7, 0.9, 1.1, 1.3, 1.6, 2.0]); print(nm, "correction at r =", g.tolist()); print("   two-stage:", np.round(vb.basis(g) @ co[nm], 2)); print("   plain regression (biased):", np.round(vb.basis(g) @ ols, 2))
coef = co["sh_da"] + co["eX_da"]; np.savez(f"{SP}/out/vb_coef.npz", coef=coef, c_d=co["sh_da"], c_x=co["eX_da"], KN=vb.KN); print("total correction coefficients:", np.round(coef, 3))
F["res"] = F.sh_da + F.eX_da - B @ coef; F["raw"] = F.sh_da + F.eX_da; F["b"] = pd.cut(F.Dp, [-99, 0, 5, 10, 15, 20, 25, 30, 35, 99]); print("dispatch + import misfit by demand bin, before and after:"); print(F.groupby("b").agg(n=("res", "size"), before=("raw", "mean"), after=("res", "mean"), disp_before=("sh_da", "mean"), disp_after=("sh_da", lambda x: (x - B[F.index.get_indexer(x.index)] @ co["sh_da"]).mean())).round(2).T.to_string())
pg = np.linspace(-80, 300, 381); 
for L_, c_ in ((60.0, 60.0), (90.0, 70.0), (130.0, 80.0)): sA = M.supply(th, pg, np.full_like(pg, L_), np.full_like(pg, c_)); sB = sA + vb.corr(coef, pg, L_); print(f"cost index {L_:.0f}: smallest slope of supply GW per EUR, A {np.diff(sA).min():.4f}, B {np.diff(sB).min():.4f}; slope at r = 0.2 / 0.6 / 1.0 / 1.4: A", [round(float(np.interp(x * L_, pg[1:], np.diff(sA))), 3) for x in (0.2, 0.6, 1.0, 1.4)], "B", [round(float(np.interp(x * L_, pg[1:], np.diff(sB))), 3) for x in (0.2, 0.6, 1.0, 1.4)])
# carry-forward test, fitting nights only
H = R[R.tr].copy(); H = H.dropna(subset=["p", "Dp", "L", "co2", "nb"]); full = pd.date_range(H.index.min().floor("D"), H.index.max().ceil("D"), freq="1h", tz=H.index.tz); H = H.reindex(full); wd = th["K_s"] * (H.p < -M.EPS) + 0.5 * th["K_s"] * (H.p.abs() <= M.EPS); S0 = M.supply(th, H.p.fillna(50).values, H.L.fillna(90).values, H.co2.fillna(70).values) - wd
uA = H.Dp - S0 - H.nb; uB = uA - vb.corr(coef, H.p.fillna(50).values, H.L.fillna(90).values); loc = H.index.tz_convert("Europe/Berlin"); night = np.asarray(loc.hour < 6); ok = (uA.notna() & uA.shift(24).notna() & H.L.shift(48).notna()).values & night
Lg, cg = H.L.shift(48).values, H.co2.shift(48).values; pA = np.full(len(H), np.nan); pB = pA.copy(); pA[ok] = vb.clear(th, H.Dp.values[ok], Lg[ok], cg[ok], (uA.shift(24) + H.nb).values[ok], None); pB[ok] = vb.clear(th, H.Dp.values[ok], Lg[ok], cg[ok], (uB.shift(24) + H.nb).values[ok], coef)
chk = vb.clear(th, H.Dp.values[ok], H.L.values[ok], H.co2.values[ok], (uA + H.nb).values[ok], None); print("check: clearing with the true shift returns the price, mean abs difference EUR:", round(float(np.nanmean(np.abs(chk - H.p.values[ok]))), 3), "| same for B:", round(float(np.nanmean(np.abs(vb.clear(th, H.Dp.values[ok], H.L.values[ok], H.co2.values[ok], (uB + H.nb).values[ok], coef) - H.p.values[ok]))), 3))
T = pd.DataFrame(dict(day=np.asarray(loc.normalize().tz_localize(None))[ok], eA=(pA - H.p.values)[ok] / 10, eB=(pB - H.p.values)[ok] / 10, dD=(H.Dp - H.Dp.shift(24)).values[ok], pers=(H.p.shift(24) - H.p).values[ok] / 10)); N = T.groupby("day").mean(); N["b"] = pd.cut(N.dD, [-99, -15, -10, -5, 5, 10, 15, 99]); rng = np.random.default_rng(0)
print(f"carry the previous night's shift, {len(N)} fitting nights: night-level MAE ct, A {N.eA.abs().mean():.3f}, B {N.eB.abs().mean():.3f}, carrying the price itself {N.pers.abs().mean():.3f}; hourly MAE A {T.eA.abs().mean():.3f} B {T.eB.abs().mean():.3f}"); d = N.eB.abs() - N.eA.abs(); x = d.values[: len(d) // 7 * 7].reshape(-1, 7).mean(1); print("   B minus A:", round(d.mean(), 3), np.round(np.percentile([x[rng.integers(0, len(x), len(x))].mean() for _ in range(4000)], [5, 95]), 3))
print(N.groupby("b").agg(n=("eA", "size"), A_abs=("eA", lambda x: x.abs().mean()), B_abs=("eB", lambda x: x.abs().mean()), A_signed=("eA", "mean"), B_signed=("eB", "mean")).round(2).T.to_string())
print("shift sd GW (night hours): A", round(float(uA[night].std()), 2), "B", round(float(uB[night].std()), 2), "| night-to-night change sd: A", round(float((uA - uA.shift(24))[night].std()), 2), "B", round(float((uB - uB.shift(24))[night].std()), 2))
